{"cards": [{"node_code": "N_9c9f5d645ec3792d", "definition": "研究不局限于单一器官系统、涉及全身多系统或整体生理状态改变的常见症状，如发热、乏力、消瘦、水肿及多系统受累表现。", "boundary": "本节点收录那些病因复杂、常需跨系统鉴别或反映全身性病理生理改变的症状。重点在于症状的全身性特征、伴随的多系统体征及鉴别诊断思路。若症状明确局限于某一特定系统（如仅咳嗽、仅腹痛），应归入对应系统节点。", "includes": ["发热、寒战、乏力、消瘦、多汗等全身性症状", "全身性水肿、淋巴结肿大等涉及多系统的体征", "不明原因多系统症状的鉴别诊断分析"], "excludes": ["明确局限于呼吸、循环、消化等单一系统的特异性症状", "特定疾病的完整诊疗方案"], "sibling_distinctions": [{"other_code": "N_1d4d757332cf9334", "rule": "本节点侧重全身性或非特异性症状；呼吸系统常见症状侧重咳嗽、呼吸困难等局限于呼吸道的表现。"}, {"other_code": "N_2a118d83c287c7af", "rule": "本节点侧重全身性表现；循环系统常见症状侧重胸痛、心悸、晕厥等与心脏血管功能直接相关的表现。"}], "cross_boundary_rule": "若症状表现为全身性（如发热伴多系统异常），主挂载本节点；若症状有明确的单一系统定位（如单纯胸痛），主挂载对应系统节点。"}, {"node_code": "N_1d4d757332cf9334", "definition": "研究呼吸系统疾病中患者主观感受及客观表现的常见症状，包括咳嗽、咳痰、呼吸困难、咯血、胸痛及声音嘶哑等。", "boundary": "本节点聚焦于呼吸道及肺部相关症状的临床特征、发生机制及鉴别诊断。涵盖上呼吸道至下呼吸道的典型症状分析。不涵盖由其他系统疾病（如心衰）引起的继发性呼吸困难，除非重点在于呼吸症状本身的鉴别。", "includes": ["咳嗽、咳痰、咯血、呼吸困难、气促等呼吸道症状", "与呼吸相关的胸痛、声音嘶哑、打鼾等表现", "呼吸系统症状的病因分析与鉴别诊断"], "excludes": ["循环系统引起的胸痛或晕厥", "神经系统引起的呼吸中枢抑制症状"], "sibling_distinctions": [{"other_code": "N_9c9f5d645ec3792d", "rule": "本节点侧重呼吸系统特异性症状；全身性常见症状侧重发热、乏力等无明确系统定位或涉及多系统的表现。"}, {"other_code": "N_2a118d83c287c7af", "rule": "本节点侧重呼吸道症状；循环系统常见症状侧重心脏泵血功能异常引起的胸痛、心悸等。"}], "cross_boundary_rule": "若症状主要源于呼吸道结构或功能异常，主挂载本节点；若呼吸困难主要由心功能不全引起，主挂载循环系统常见症状。"}, {"node_code": "N_2a118d83c287c7af", "definition": "研究循环系统疾病中患者主观感受及客观表现的常见症状，包括胸痛、心悸、晕厥、呼吸困难、水肿及脉搏异常等。", "boundary": "本节点聚焦于心脏、血管及血液循环功能异常引起的症状。涵盖心源性胸痛、心律失常相关心悸、血流动力学改变导致的晕厥及水肿等。不涵盖由肺部疾病直接引起的呼吸困难，除非重点在于心源性鉴别。", "includes": ["胸痛、心悸、晕厥、黑矇等心脏相关症状", "下肢水肿、颈静脉怒张等循环淤血表现", "脉搏异常、血压波动等循环功能相关症状"], "excludes": ["呼吸系统原发性的咳嗽、咯血", "消化系统原发性的腹痛、腹泻"], "sibling_distinctions": [{"other_code": "N_1d4d757332cf9334", "rule": "本节点侧重循环系统症状；呼吸系统常见症状侧重咳嗽、咯血等呼吸道表现。两者在呼吸困难上可能有交叉，需根据病因侧重区分。"}, {"other_code": "N_9c9f5d645ec3792d", "rule": "本节点侧重循环系统特异性症状；全身性常见症状侧重发热、乏力等全身性表现。"}], "cross_boundary_rule": "若症状主要源于心脏泵血或血管功能异常，主挂载本节点；若胸痛由胸膜炎等呼吸系统疾病引起，主挂载呼吸系统常见症状。"}]}
